import dataclasses
from typing import Optional, Dict, Any

@dataclasses.dataclass
class SpeechConfig:
    api_key: str
    region: str
    language_code: Optional[str] = None
    sample_rate_hz: Optional[int] = None
    enable_automatic_punctuation: Optional[bool] = None

@dataclasses.dataclass
class SpeechResult:
    text: str
    is_final: bool
    confidence: Optional[float] = None
    language: Optional[str] = None

def normalize_azure_speech_event(event: Any) -> SpeechResult:
    """Normalizes an Azure Speech SDK event to a common SpeechResult format."""
    if hasattr(event.result, 'text'):
        return SpeechResult(
            text=event.result.text,
            is_final=event.result.reason == event.result.reason.RecognizedSpeech,
            confidence=getattr(event.result, 'confidence', None),
            language=getattr(event.result, 'language', None)
        )
    return SpeechResult(text="", is_final=False)

import azure.cognitiveservices.speech as speechsdk
from speech_models import SpeechConfig

def create_speech_recognizer(config: SpeechConfig, audio_stream: speechsdk.audio.PushAudioInputStream = None):
    speech_config = speechsdk.SpeechConfig(subscription=config.api_key, region=config.region)
    if config.language_code:
        speech_config.speech_recognition_language = config.language_code
    if config.enable_automatic_punctuation:
        speech_config.enable_punctuation = config.enable_automatic_punctuation

    if audio_stream:
        audio_config = speechsdk.audio.AudioConfig(stream=audio_stream)
    else:
        audio_config = speechsdk.audio.AudioConfig(use_default_microphone=True)

    return speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

from google.cloud import translate

def translate_caption(text: str, target_language: str, project_id: str) -> str:
    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
        }
    )

    for translation in response.translations:
        return translation.translated_text
    return text

import google.generativeai as genai
import os

def check_content_safety(text: str) -> dict:
    # Configure the Google Generative AI client
    # Make sure to set GOOGLE_API_KEY environment variable
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))

    # Use a model that supports safety settings, e.g., gemini-pro
    model = genai.GenerativeModel('gemini-pro')

    # For safety checks, we're interested in the prompt feedback and safety ratings
    # We'll generate a trivial response to get the safety attributes of the input text.
    try:
        response = model.generate_content(
            text,
            safety_settings=[
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
            ],
            stream=False # Not streaming the response for a simple safety check
        )

        # If the prompt was blocked, response.prompt_feedback will contain the reason
        if response.prompt_feedback and response.prompt_feedback.safety_ratings:
            return {
                "is_safe": False,
                "safety_ratings": [{'category': r.category.name, 'probability': r.probability.name} for r in response.prompt_feedback.safety_ratings]
            }

        # If not blocked, it's considered safe for the defined thresholds
        return {"is_safe": True, "safety_ratings": []}

    except Exception as e:
        # Handle cases where the API call itself fails or other errors occur
        print(f"Error checking content safety: {e}")
        return {"is_safe": False, "error": str(e)}

